mapper.select:
SELECT *
FROM wms_location_inventory
WHERE warehouse_id = #{warehouseId}
  AND erp_tenant_id = #{erpTenantId}
  AND sku_code = #{skuCode}
  AND quality = #{quality}
  AND quantity > reserved_quantity
  AND deleted = 0
ORDER BY location_id, id
FOR UPDATE

SELECT *
FROM wms_location_inventory
WHERE tenant_id = #{key.tenantId}
  AND wms_tenant_id = #{key.wmsTenantId}
  AND erp_tenant_id = #{key.erpTenantId}
  AND warehouse_id = #{key.warehouseId}
  AND location_id = #{key.locationId}
  AND sku_code = #{key.skuCode}
  AND quality = #{key.quality}
  AND deleted = 0
FOR UPDATE

SELECT *
FROM wms_location_inventory
WHERE tenant_id = #{tenantId}
  AND wms_tenant_id = #{wmsTenantId}
  AND erp_tenant_id = #{erpTenantId}
  AND warehouse_id = #{warehouseId}
  AND sku_code = #{skuCode}
  AND quality = #{quality}
  AND quantity > reserved_quantity
  AND deleted = 0
ORDER BY id
FOR UPDATE

SELECT COALESCE(SUM(quantity), 0)
FROM wms_location_inventory
WHERE wms_tenant_id = #{wmsTenantId}
  AND warehouse_id = #{warehouseId}
  AND deleted = 0

SELECT COALESCE(SUM(reserved_quantity), 0)
FROM wms_location_inventory
WHERE wms_tenant_id = #{wmsTenantId}
  AND warehouse_id = #{warehouseId}
  AND deleted = 0

mapper.update:
UPDATE wms_location_inventory
SET quantity = quantity + #{quantity}, version = version + 1
WHERE id = #{id} AND version = #{version}

UPDATE wms_location_inventory
SET quantity = quantity - #{quantity}, version = version + 1
WHERE id = #{id}
  AND quantity - reserved_quantity >= #{quantity}
  AND version = #{version}

UPDATE wms_location_inventory
SET reserved_quantity = reserved_quantity + #{quantity}, version = version + 1
WHERE id = #{id}
  AND quantity - reserved_quantity >= #{quantity}
  AND version = #{version}

UPDATE wms_location_inventory
SET reserved_quantity = reserved_quantity - #{quantity}, version = version + 1
WHERE id = #{id}
  AND reserved_quantity >= #{quantity}
  AND version = #{version}

UPDATE wms_location_inventory
SET quantity = quantity - #{quantity},
    reserved_quantity = reserved_quantity - #{quantity},
    version = version + 1
WHERE id = #{id}
  AND quantity >= #{quantity}
  AND reserved_quantity >= #{quantity}
  AND version = #{version}
